package com.pranit.helpdesk.service;
import com.pranit.helpdesk.dto.*; import com.pranit.helpdesk.entity.*; import com.pranit.helpdesk.exception.NotFoundException; import com.pranit.helpdesk.model.*; import com.pranit.helpdesk.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.List;
@Service public class TicketService{private final TicketRepository tickets;private final UserRepository users;private final CommentRepository comments;public TicketService(TicketRepository t,UserRepository u,CommentRepository c){tickets=t;users=u;comments=c;}private User user(String name){return users.findByUsername(name).orElseThrow(()->new NotFoundException("User not found"));}public Ticket create(CreateTicketRequest r,String name){Ticket t=new Ticket();t.setTitle(r.title());t.setDescription(r.description());if(r.priority()!=null)t.setPriority(r.priority());t.setCreatedBy(user(name));return tickets.save(t);}public List<Ticket> mine(String name){return tickets.findByCreatedByIdOrderByCreatedAtDesc(user(name).getId());}public List<Ticket> assigned(String name){return tickets.findByAssignedToIdOrderByCreatedAtDesc(user(name).getId());}public Ticket get(Long id){return tickets.findById(id).orElseThrow(()->new NotFoundException("Ticket not found"));}public Ticket update(Long id,UpdateTicketRequest r){Ticket t=get(id);if(r.title()!=null&&!r.title().isBlank())t.setTitle(r.title());if(r.description()!=null&&!r.description().isBlank())t.setDescription(r.description());if(r.priority()!=null)t.setPriority(r.priority());if(r.status()!=null){t.setStatus(r.status());if(r.status()==TicketStatus.RESOLVED)t.setResolvedAt(LocalDateTime.now());}return tickets.save(t);}public Ticket assign(Long id,String agent){Ticket t=get(id);User a=user(agent);if(a.getRole()!=Role.AGENT&&a.getRole()!=Role.ADMIN)throw new IllegalArgumentException("User is not an agent");t.setAssignedTo(a);if(t.getStatus()==TicketStatus.OPEN)t.setStatus(TicketStatus.ASSIGNED);return tickets.save(t);}public Comment comment(Long id,String name,String message){Comment c=new Comment();c.setTicket(get(id));c.setAuthor(user(name));c.setMessage(message);return comments.save(c);}public List<Comment> comments(Long id){get(id);return comments.findByTicketIdOrderByCreatedAtAsc(id);}public long count(TicketStatus s){return tickets.countByStatus(s);}}
